/* =========================================================
   CHECK MAIN MODULE ACCESS
   ========================================================= */

function canAFRoleAccessModule(moduleName) {

const role =
getAFCurrentRole();

  if (!role) {
    return false;
  }


const moduleAccess = {

materialProduction: [
      "Director"
    ],

stockInventory: [
      "Director"
    ],

salesCustomers: [
      "Director",
      "Secretary"
    ],

    suppliers: [
      "Director",
      "Secretary"
    ],

    expenses: [
      "Director",
      "Secretary"
    ],

staffHR: [
      "Director",
      "Manager",
      "HR",
      "Secretary",
      "Team Leader"
    ],

    reports: [
      "Director",
      "HR",
      "Secretary"
    ],

systemSettings: [
      "Director"
    ],

washingTarget: [
      "Director"
    ],

washingRecords: [
      "Director"
    ],
   poleStandardWeights: [
      "Director"
   ],

  };


const allowedRoles =
moduleAccess[moduleName] || [];


  return allowedRoles.includes(role);

}


/* =========================================================
   OPEN MAIN MODULE SAFELY
   ========================================================= */

function openRoleModule(moduleName) {

  if (
    !canAFRoleAccessModule(moduleName)
  ) {

const role =
getAFCurrentRole() ||
      "This user";

    alert(
      "Access Denied\n\n" +
      role +
      " does not have access to this module."
    );

    return;

  }


  switch (moduleName) {

    case "materialProduction":

showMessage(
        "Material & Production"
      );

      break;


    case "stockInventory":

showMessage(
        "Stock & Inventory"
      );

      break;


    case "salesCustomers":

clientRegistration();

      break;


    case "suppliers":

supplierManagement();

      break;


    case "expenses":

showMessage(
        "Expenses"
      );

      break;


    case "staffHR":

staffHR();

      break;


    case "reports":

monthlyClientSummary();

      break;


    case "systemSettings":

systemSettings();

      break;


    case "washingTarget":

setWashingTarget();

      break;


   case "washingRecords":

viewWashingRecords();

      break;


    case "poleStandardWeights":

managePoleStandardWeights();
closeAFMobileMenu();

      break;

  }

}

/* =========================================================
   CHECK QUICK ACTION ACCESS
   ========================================================= */

function canAFRoleRunAction(actionName) {

const role =
getAFCurrentRole();

  if (!role) {
    return false;
  }


const actionAccess = {

recordMaterialIn: [
      "Director",
      "Secretary"
    ],

recordWashing: [
      "Director",
      "Manager"
    ],
recordProduction: [
      "Director",
      "Manager"
    ],

checkStock: [
      "Director",
      "Manager"
    ],

planProduction: [
      "Director"
    ],

recordDelivery: [
      "Director"
    ]

  };


const allowedRoles =
actionAccess[actionName] || [];


  return allowedRoles.includes(role);

}


/* =========================================================
   RUN QUICK ACTION SAFELY
   ========================================================= */

function runRoleAction(actionName) {

  if (
    !canAFRoleRunAction(actionName)
  ) {

const role =
getAFCurrentRole() ||
      "This user";

    alert(
      "Access Denied\n\n" +
      role +
      " is not authorised to perform this action."
    );

    return;

  }


  switch (actionName) {

    case "recordMaterialIn":

recordMaterialIn();

      break;


    case "recordWashing":

recordWashing();

      break;


    case "recordProduction":

recordProduction();

      break;


    case "checkStock":

showMessage(
        "Check Stock"
      );

      break;


    case "planProduction":

showMessage(
        "Plan Production"
      );

      break;


    case "recordDelivery":

showMessage(
        "Record Delivery"
      );

      break;

  }

}


/* =========================================================
   RECORD / EDIT / DELETE AUTHORITY
   ========================================================= */

function canAFRecord(recordArea) {

const role =
getAFCurrentRole();


  if (role === "Director") {
    return true
  }


  if (role === "Secretary") {

const secretaryRecordAreas = [
      "accounts",
      "expenses",
      "sales",
      "customers",
      "suppliers",
      "attendance",
      "allowance",
      "advances",
      "payroll",
      "documents",
      "administration",
      "marketing"
    ];

    return secretaryRecordAreas.includes(
recordArea
    );

  }


  if (role === "HR") {

const hrRecordAreas = [
      "employees",
      "teams",
      "attendance",
      "allowance",
      "advances",
      "payroll",
      "documents",
      "hr"
    ];

    return hrRecordAreas.includes(
recordArea
    );

  }


  if (role === "Manager") {

const managerRecordAreas = [
      "washing",
      "production"
    ];

    return managerRecordAreas.includes(
recordArea
    );

  }


  return false;

}


/* =========================================================
   EDIT AUTHORITY
   Director controls saved-record editing.
   ========================================================= */

function canAFEditSavedRecord() {

  return getAFCurrentRole() ===
    "Director";

}


/* =========================================================
   DELETE AUTHORITY
   Director only.
   ========================================================= */

function canAFDeleteSavedRecord() {

  return getAFCurrentRole() ===
    "Director";

}


/* =========================================================
   REQUIRE EDIT AUTHORITY
   ========================================================= */

function requireAFEditAuthority() {

  if (canAFEditSavedRecord()) {
    return true;
  }


  alert(
    "Access Denied\n\n" +
    "Only the Director can edit saved records."
  );


  return false;

}


/* =========================================================
   REQUIRE DELETE AUTHORITY
   ========================================================= */

function requireAFDeleteAuthority() {

  if (canAFDeleteSavedRecord()) {
    return true;
  }


  alert(
    "Access Denied\n\n" +
    "Only the Director can delete saved records."
  );


  return false;

}
