function afManagerIsLoggedIn() {
const user =
typeof getAFCurrentUser === "function"
      ? getAFCurrentUser()
      : JSON.parse(
localStorage.getItem("currentUser") || "null"
        );

  return !!(
    user &&
user.role === "Manager"
  );
}


function afManagerEscape(value) {
  if (
typeof escapeSettingsText === "function"
  ) {
    return escapeSettingsText(
      String(value ?? "")
    );
  }

const div =
document.createElement("div");

div.textContent =
    String(value ?? "");

  return div.innerHTML;
}


function afManagerFormatMinutes(minutes) {
const total =
Math.max(
      Number(minutes || 0),
      0
    );

const hours =
Math.floor(total / 60);

const mins =
Math.round(total % 60);

  return (
    hours +
    "h " +
mins +
    "m"
  );
}


function afManagerFormatTime(time) {
  if (!time) {
    return "—";
  }

  if (
    typeof window !== "undefined" &&
    typeof window.formatAFTime === "function"
  ) {
    return afManagerEscape(
      window.formatAFTime(time)
    );
  }

  return afManagerEscape(time);
}

function afManagerPercent(
  value,
  total
) {
const number =
    Number(value || 0);

const denominator =
    Number(total || 0);

  if (denominator <= 0) {
    return "0.0%";
  }

  return (
    (
      number /
      denominator *
      100
    ).toFixed(1) +
    "%"
  );
}


function afManagerDateString(date) {
const year =
date.getFullYear();

const month =
    String(
date.getMonth() + 1
    ).padStart(2, "0");

const day =
    String(
date.getDate()
    ).padStart(2, "0");

  return (
    year +
    "-" +
    month +
    "-" +
    day
  );
}


function afManagerReadableDate(
dateString
) {
  if (!dateString) {
    return "—";
  }

const date =
    new Date(
dateString +
      "T00:00:00"
    );

  if (
Number.isNaN(
date.getTime()
    )
  ) {
    return afManagerEscape(
dateString
    );
  }

  return date.toLocaleDateString(
    undefined,
    {
      day: "numeric",
      month: "short",
      year: "numeric"
    }
  );
}


