/* =========================================================
   EDIT MATERIAL RECORD
   ========================================================= */


function editMaterialRecord(id) {
  const records = afMaterialReadRecords();

  const record = records.find(
    item => String(item.id) === String(id)
  );

  if (!record) {
    alert("Material record not found.");
    return;
  }

  const isClient =
    String(record.materialSource || "").toLowerCase() === "client";

  if (isClient) {
    if (!record.clientOrigin) {
      record.clientOrigin = record.clientAddress || "";
    }

    if (!Array.isArray(record.servicePaymentHistory)) {
      record.servicePaymentHistory = [];
    }

    afMaterialRecalculateClientService(record);
  }

  const modal = document.createElement("div");

  modal.style.cssText = `
    position:fixed;
    inset:0;
    background:rgba(0,0,0,.55);
    display:flex;
    align-items:center;
    justify-content:center;
    z-index:10000;
    font-family:Arial,sans-serif;
  `;

  const paymentRows =
    isClient &&
    Array.isArray(record.servicePaymentHistory) &&
    record.servicePaymentHistory.length
      ? record.servicePaymentHistory
          .map(payment => `
            <tr>
              <td>${afMaterialEscape(payment.date || "")}</td>
              <td>${afMaterialEscape(payment.receiptNo || "")}</td>
              <td>${afMaterialEscape(payment.method || "")}</td>
              <td>${afMaterialEscape(payment.reference || "")}</td>
              <td style="text-align:right">${afMaterialMoney(payment.amount || 0)}</td>
              <td>
                <button type="button"
                  data-print-service-payment="${afMaterialEscape(payment.id || "")}"
                  style="padding:5px 8px;border:0;border-radius:5px;background:#0b5d3b;color:white;cursor:pointer">
                  Print
                </button>
              </td>
            </tr>
          `)
          .join("")
      : `
        <tr>
          <td colspan="6" style="text-align:center;padding:10px">
            No payments recorded yet.
          </td>
        </tr>
      `;

  modal.innerHTML = `
  <div style="
    background:white;
    width:760px;
    max-width:96%;
    max-height:94vh;
    overflow:auto;
    border-radius:14px;
    padding:24px;
    box-shadow:0 10px 40px rgba(0,0,0,.3);
  ">
    <h2 style="margin-top:0;color:#0b5d3b">
      ${isClient ? "Client Processing Job" : "Edit Company Material Record"}
    </h2>

    ${
      isClient
        ? `
          <div style="background:#eef8f2;padding:12px;border-radius:8px;margin-bottom:14px">
            <b>Job No:</b> ${afMaterialEscape(record.serviceJobNumber || "-")}<br>
            <b>Batch:</b> ${afMaterialEscape(record.batchNumber || "-")}<br>
            <b>Status:</b> <span id="editServiceStatus">${afMaterialEscape(record.serviceStatus || "-")}</span>
          </div>
        `
        : `
          <div style="background:#eef8f2;padding:12px;border-radius:8px;margin-bottom:14px">
            <b>Batch:</b> ${afMaterialEscape(record.batchNumber || "-")}<br>
            <b>Washing Cycle:</b> ${afMaterialEscape(record.washingCycleNumber || "-")}
          </div>
        `
    }

    <label>Date</label>
    <input id="editMaterialDate" type="date"
      value="${afMaterialEscape(record.date || "")}"
      style="width:100%;padding:10px;margin:6px 0 14px">

    ${
      isClient
        ? `
          <label>Client Name</label>
          <input id="editClientName" type="text"
            value="${afMaterialEscape(record.clientName || "")}"
            style="width:100%;padding:10px;margin:6px 0 14px">

          <label>Client Contact No.</label>
          <input id="editClientPhone" type="text"
            value="${afMaterialEscape(record.clientPhone || "")}"
            style="width:100%;padding:10px;margin:6px 0 14px">

          <label>Origin of Kavera</label>
          <input id="editClientOrigin" type="text"
            value="${afMaterialEscape(record.clientOrigin || record.clientAddress || "")}"
            style="width:100%;padding:10px;margin:6px 0 14px">

          <label>Service Required</label>
          <select id="editClientService"
            style="width:100%;padding:10px;margin:6px 0 14px">
            <option value="washing" ${record.clientService === "washing" ? "selected" : ""}>Washing Only</option>
            <option value="washing_pelletizing" ${record.clientService === "washing_pelletizing" ? "selected" : ""}>Washing + Pelletizing</option>
            <option value="pelletizing" ${record.clientService === "pelletizing" ? "selected" : ""}>Pelletizing Only</option>
          </select>
        `
        : ""
    }

    <label>Material Type</label>
    <select id="editMaterialType"
      style="width:100%;padding:10px;margin:6px 0 14px">
      <option ${record.materialType === "HDPE" ? "selected" : ""}>HDPE</option>
      <option ${record.materialType === "LDPE" ? "selected" : ""}>LDPE</option>
      <option ${record.materialType === "PP" ? "selected" : ""}>PP</option>
      <option ${record.materialType === "Mixed Plastic" ? "selected" : ""}>Mixed Plastic</option>
    </select>

    <label>Quantity / Gross Weight Received (kg)</label>
    <input id="editGrossWeight" type="number" min="0" step="0.01"
      value="${Number(record.grossWeight || 0)}"
      style="width:100%;padding:10px;margin:6px 0 14px">

    ${
      isClient
        ? `
          <div id="editWashingBillingSection">
            <label>Washing Rate per kg (UGX)</label>
            <input id="editWashingRate" type="number" min="0" step="1"
              value="${Number(record.washingRatePerKg || 0)}"
              style="width:100%;padding:10px;margin:6px 0 14px">
          </div>

          <div id="editPelletBillingSection">
            <label>Pellets kg Produced</label>
            <input id="editPelletWeight" type="number" min="0" step="0.01"
              value="${Number(record.actualPelletWeight || record.pelletWeight || 0)}"
              style="width:100%;padding:10px;margin:6px 0 14px">

            <label>Pelletizing Rate per kg (UGX)</label>
            <input id="editPelletRate" type="number" min="0" step="1"
              value="${Number(record.pelletizingRatePerKg || 0)}"
              style="width:100%;padding:10px;margin:6px 0 14px">

            <div style="background:#fff7e6;padding:10px;border-radius:7px;font-size:12px;color:#765400;margin-bottom:14px">
              For Washing + Pelletizing, complete these pelletizing details on this same job when pellets are ready.
            </div>
          </div>

          <label>Truck Cost (UGX)</label>
          <input id="editServiceTruckCost" type="number" min="0" step="1" value="${Number(record.serviceTruckCost || 0)}" style="width:100%;padding:10px;margin:6px 0 14px">
          <label>Truck Particulars</label>
          <input id="editServiceTruckParticulars" type="text" value="${afMaterialEscape(record.serviceTruckParticulars || "")}" style="width:100%;padding:10px;margin:6px 0 14px">
          <label>Miscellaneous Expenses / Charges (UGX)</label>
          <input id="editServiceMiscExpenses" type="number" min="0" step="1" value="${Number(record.serviceMiscExpenses || 0)}" style="width:100%;padding:10px;margin:6px 0 14px">
          <label>Reason for Miscellaneous Expense / Charge</label>
          <input id="editServiceMiscReason" type="text" value="${afMaterialEscape(record.serviceMiscReason || "")}" style="width:100%;padding:10px;margin:6px 0 14px">

          <label>Discount (UGX)</label>
          <input id="editServiceDiscount" type="number" min="0" step="1"
            value="${Number(record.serviceDiscount || 0)}"
            style="width:100%;padding:10px;margin:6px 0 14px">

          <div id="editClientServiceSummary" style="
            background:#eef8f2;padding:15px;border-radius:8px;margin:15px 0;
          ">
            <b>Washing Charge:</b> <span id="editWashingChargePreview">${afMaterialMoney(record.washingCharge || 0)}</span><br><br>
            <b>Pelletizing Charge:</b> <span id="editPelletChargePreview">${afMaterialMoney(record.pelletizingCharge || 0)}</span><br><br>
            <b>Truck Cost:</b> <span id="editTruckCostPreview">${afMaterialMoney(record.serviceTruckCost || 0)}</span><br><br>
            <b>Miscellaneous:</b> <span id="editMiscPreview">${afMaterialMoney(record.serviceMiscExpenses || 0)}</span><br><br>
            <b>Gross Service Charge:</b> <span id="editSubtotalPreview">${afMaterialMoney(record.serviceSubtotal || 0)}</span><br><br>
            <b>Discount:</b> <span id="editDiscountPreview">${afMaterialMoney(record.serviceDiscount || 0)}</span><br><br>
            <b>Net Service Charge:</b> <span id="editTotalDuePreview">${afMaterialMoney(record.serviceTotalDue || 0)}</span><br><br>
            <b>Total Paid:</b> <span id="editTotalPaidPreview">${afMaterialMoney(record.serviceAmountPaid || 0)}</span><br><br>
            <b>Outstanding Balance:</b> <span id="editBalancePreview">${afMaterialMoney(record.serviceBalance || 0)}</span>
          </div>

          <h3 style="color:#0b5d3b;margin-bottom:8px">Instalment Payments</h3>

          <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
            <label>
              Payment Date
              <input id="newServicePaymentDate" type="date"
                value="${new Date().toISOString().split("T")[0]}"
                style="width:100%;box-sizing:border-box;padding:9px;margin-top:4px">
            </label>

            <label>
              Amount (UGX)
              <input id="newServicePaymentAmount" type="number" min="0" step="1"
                style="width:100%;box-sizing:border-box;padding:9px;margin-top:4px">
            </label>

            <label>
              Method
              <select id="newServicePaymentMethod"
                style="width:100%;box-sizing:border-box;padding:9px;margin-top:4px">
                <option>Cash</option>
                <option>Mobile Money</option>
                <option>Bank Transfer</option>
                <option>Cheque</option>
              </select>
            </label>

            <label>
              Reference / Transaction No.
              <input id="newServicePaymentReference" type="text"
                style="width:100%;box-sizing:border-box;padding:9px;margin-top:4px">
            </label>
          </div>

          <button id="addServiceInstalment" type="button" style="
            width:100%;margin-top:10px;padding:10px;border:0;border-radius:7px;
            background:#164e63;color:white;font-weight:bold;cursor:pointer;
          ">+ Save Instalment Payment</button>

          <div style="overflow:auto;margin-top:14px;border:1px solid #ddd;border-radius:8px">
            <table style="width:100%;min-width:650px;border-collapse:collapse;font-size:12px">
              <thead>
                <tr style="background:#f6f6f6">
                  <th>Date</th><th>Receipt No.</th><th>Method</th>
                  <th>Reference</th><th>Amount</th><th>Receipt</th>
                </tr>
              </thead>
              <tbody>${paymentRows}</tbody>
            </table>
          </div>
        `
        : `
          <label>Dirt / Waste (%)</label>
          <input id="editDirtPercent" type="number" min="0" max="100" step="0.01"
            value="${Number(record.dirtPercent || 0)}"
            style="width:100%;padding:10px;margin:6px 0 14px">

          <label>Purchase Price per kg (UGX)</label>
          <input id="editPricePerKg" type="number" min="0" step="1"
            value="${Number(record.pricePerKg || 0)}"
            style="width:100%;padding:10px;margin:6px 0 14px">

          <label>Transport Cost (UGX)</label>
          <input id="editTransportCost" type="number" min="0" step="1"
            value="${Number(record.transportCost || 0)}"
            style="width:100%;padding:10px;margin:6px 0 14px">

          <label>Miscellaneous Expenses (UGX)</label>
          <input id="editCompanyMiscExpenses" type="number" min="0" step="1"
            value="${Number(record.miscellaneousExpenses || 0)}"
            style="width:100%;padding:10px;margin:6px 0 14px">

          <label>Reason / Particulars for Miscellaneous Expense</label>
          <input id="editCompanyMiscReason" type="text"
            value="${afMaterialEscape(record.miscellaneousReason || "")}"
            style="width:100%;padding:10px;margin:6px 0 14px">

          <div id="editCompanySummary" style="
            background:#eef8f2;padding:15px;border-radius:8px;margin:15px 0;
          ">
            <b>Net Usable Weight:</b> <span id="editCompanyNetPreview">0 kg</span><br><br>
            <b>Total Cost:</b> <span id="editCompanyCostPreview">UGX 0</span>
          </div>
        `
    }

    <div style="display:flex;gap:10px;margin-top:18px">
      <button id="updateMaterialRecord" style="
        flex:1;padding:12px;border:0;border-radius:8px;
        background:#0b5d3b;color:white;cursor:pointer;font-weight:bold;
      ">💾 Update Record</button>

      <button id="cancelEditMaterial" style="
        flex:1;padding:12px;border:1px solid #ccc;border-radius:8px;
        background:white;cursor:pointer;
      ">Cancel</button>
    </div>
  </div>
  `;

  document.body.appendChild(modal);

  modal.querySelectorAll("th,td").forEach(cell => {
    cell.style.padding = "7px";
    cell.style.borderBottom = "1px solid #eee";
  });

  function refreshEditPreview() {
    const grossKg =
      Number(modal.querySelector("#editGrossWeight")?.value || 0);

    if (!isClient) {
      const dirtPercent =
        Number(modal.querySelector("#editDirtPercent")?.value || 0);
      const pricePerKg =
        Number(modal.querySelector("#editPricePerKg")?.value || 0);
      const transportCost =
        Math.max(Number(modal.querySelector("#editTransportCost")?.value || 0), 0);
      const miscExpense =
        Math.max(Number(modal.querySelector("#editCompanyMiscExpenses")?.value || 0), 0);

      const netKg =
        grossKg * (1 - dirtPercent / 100);

      const totalCost =
        (netKg * pricePerKg) + transportCost + miscExpense;

      const netPreview =
        modal.querySelector("#editCompanyNetPreview");
      const costPreview =
        modal.querySelector("#editCompanyCostPreview");

      if (netPreview) {
        netPreview.textContent =
          netKg.toLocaleString() + " kg";
      }

      if (costPreview) {
        costPreview.textContent =
          afMaterialMoney(totalCost);
      }

      return;
    }

    const service =
      modal.querySelector("#editClientService").value;

    const washingSection =
      modal.querySelector("#editWashingBillingSection");

    const pelletSection =
      modal.querySelector("#editPelletBillingSection");

    washingSection.style.display =
      service === "washing" ||
      service === "washing_pelletizing"
        ? "block"
        : "none";

    pelletSection.style.display =
      service === "pelletizing" ||
      service === "washing_pelletizing"
        ? "block"
        : "none";

    const washingRate =
      Number(modal.querySelector("#editWashingRate").value || 0);

    const pelletKg =
      Number(modal.querySelector("#editPelletWeight").value || 0);

    const pelletRate =
      Number(modal.querySelector("#editPelletRate").value || 0);

    const washingCharge =
      service === "washing" ||
      service === "washing_pelletizing"
        ? grossKg * washingRate
        : 0;

    const pelletCharge =
      service === "pelletizing" ||
      service === "washing_pelletizing"
        ? pelletKg * pelletRate
        : 0;

    const truckCostValue = Math.max(Number(modal.querySelector("#editServiceTruckCost").value || 0), 0);
    const miscValue = Math.max(Number(modal.querySelector("#editServiceMiscExpenses").value || 0), 0);
    const subtotal =
      washingCharge + pelletCharge + truckCostValue + miscValue;

    const discount =
      Math.min(
        Math.max(
          Number(
            modal.querySelector("#editServiceDiscount").value
          ) || 0,
          0
        ),
        subtotal
      );

    const totalDue =
      Math.max(subtotal - discount, 0);

    const totalPaid =
      afMaterialPaymentTotal(record);

    const balance =
      Math.max(totalDue - totalPaid, 0);

    modal.querySelector("#editWashingChargePreview").textContent =
      afMaterialMoney(washingCharge);

    modal.querySelector("#editPelletChargePreview").textContent =
      afMaterialMoney(pelletCharge);

    modal.querySelector("#editTruckCostPreview").textContent = afMaterialMoney(truckCostValue);
    modal.querySelector("#editMiscPreview").textContent = afMaterialMoney(miscValue);
    modal.querySelector("#editSubtotalPreview").textContent =
      afMaterialMoney(subtotal);

    modal.querySelector("#editDiscountPreview").textContent =
      afMaterialMoney(discount);

    modal.querySelector("#editTotalDuePreview").textContent =
      afMaterialMoney(totalDue);

    modal.querySelector("#editTotalPaidPreview").textContent =
      afMaterialMoney(totalPaid);

    modal.querySelector("#editBalancePreview").textContent =
      afMaterialMoney(balance);
  }

  if (isClient) {
    [
      "#editGrossWeight",
      "#editWashingRate",
      "#editPelletWeight",
      "#editPelletRate",
      "#editServiceTruckCost",
      "#editServiceMiscExpenses",
      "#editServiceDiscount"
    ].forEach(selector => {
      modal.querySelector(selector)?.addEventListener(
        "input",
        refreshEditPreview
      );
    });

    modal.querySelector("#editClientService")
      .addEventListener("change", refreshEditPreview);

    modal.querySelectorAll("[data-print-service-payment]")
      .forEach(button => {
        button.onclick = () => {
          const paymentId =
            button.getAttribute("data-print-service-payment");

          const payment =
            (record.servicePaymentHistory || [])
              .find(item => String(item.id) === String(paymentId));

          if (payment) {
            afMaterialPrintServiceReceipt(record, payment);
          }
        };
      });

    modal.querySelector("#addServiceInstalment").onclick = () => {
      /*
       * First save the latest service figures into the record so
       * the outstanding balance is correct before accepting money.
       */
      const service =
        modal.querySelector("#editClientService").value;

      const grossKg =
        Number(modal.querySelector("#editGrossWeight").value || 0);

      const washingRate =
        Number(modal.querySelector("#editWashingRate").value || 0);

      const pelletKg =
        Number(modal.querySelector("#editPelletWeight").value || 0);

      const pelletRate =
        Number(modal.querySelector("#editPelletRate").value || 0);

      record.clientService = service;
      record.grossWeight = grossKg;
      record.washingRatePerKg = washingRate;
      record.pelletWeight = pelletKg;
      record.actualPelletWeight = pelletKg;
      record.pelletizingRatePerKg = pelletRate;
      record.serviceTruckCost = Math.max(Number(modal.querySelector("#editServiceTruckCost").value || 0), 0);
      record.serviceTruckParticulars = modal.querySelector("#editServiceTruckParticulars").value.trim();
      record.serviceMiscExpenses = Math.max(Number(modal.querySelector("#editServiceMiscExpenses").value || 0), 0);
      record.serviceMiscReason = modal.querySelector("#editServiceMiscReason").value.trim();
      record.serviceDiscount =
        Number(modal.querySelector("#editServiceDiscount").value || 0);

      afMaterialRecalculateClientService(record);

      const amount =
        Number(
          modal.querySelector("#newServicePaymentAmount").value
        ) || 0;

      if (amount <= 0) {
        alert("Please enter the instalment amount.");
        return;
      }

      let payment;

      try {
        payment = afMaterialAddPayment(record, {
          amount,
          date:
            modal.querySelector("#newServicePaymentDate").value,
          method:
            modal.querySelector("#newServicePaymentMethod").value,
          reference:
            modal.querySelector("#newServicePaymentReference").value
        });
      } catch (error) {
        alert(error.message || "Could not save the payment.");
        return;
      }

      afMaterialSaveRecords(records);

      alert(
        "Instalment payment saved successfully.\n\n" +
        "Receipt: " + payment.receiptNo + "\n" +
        "Amount: " + afMaterialMoney(payment.amount) + "\n" +
        "Outstanding: " + afMaterialMoney(record.serviceBalance)
      );

      afMaterialPrintServiceReceipt(record, payment);

      modal.remove();
      editMaterialRecord(id);
    };
  } else {
    [
      "#editGrossWeight",
      "#editDirtPercent",
      "#editPricePerKg",
      "#editTransportCost",
      "#editCompanyMiscExpenses"
    ].forEach(selector => {
      modal.querySelector(selector)?.addEventListener(
        "input",
        refreshEditPreview
      );
    });
  }

  modal.querySelector("#cancelEditMaterial").onclick = () => {
    modal.remove();
  };

  modal.querySelector("#updateMaterialRecord").onclick = () => {
    const grossKg =
      Number(modal.querySelector("#editGrossWeight").value || 0);

    if (grossKg <= 0) {
      alert("Please enter the quantity / gross weight received.");
      return;
    }

    record.date =
      modal.querySelector("#editMaterialDate").value;

    record.materialType =
      modal.querySelector("#editMaterialType").value;

    record.grossWeight = grossKg;

    if (isClient) {
      const clientName =
        modal.querySelector("#editClientName").value.trim();

      const clientPhone =
        modal.querySelector("#editClientPhone").value.trim();

      const clientOrigin =
        modal.querySelector("#editClientOrigin").value.trim();

      const service =
        modal.querySelector("#editClientService").value;

      const washingRate =
        Number(modal.querySelector("#editWashingRate").value || 0);

      const pelletKg =
        Number(modal.querySelector("#editPelletWeight").value || 0);

      const pelletRate =
        Number(modal.querySelector("#editPelletRate").value || 0);

      if (!clientName) {
        alert("Please enter the client name.");
        return;
      }

      if (!clientPhone) {
        alert("Please enter the client contact number.");
        return;
      }

      if (!clientOrigin) {
        alert("Please enter the origin of Kavera.");
        return;
      }

      if (
        (
          service === "washing" ||
          service === "washing_pelletizing"
        ) &&
        washingRate <= 0
      ) {
        alert("Please enter the washing rate per kg.");
        return;
      }

      if (pelletKg > 0 && pelletRate <= 0) {
        alert("Please enter the pelletizing rate per kg.");
        return;
      }

      record.materialSource = "client";
      record.clientName = clientName;
      record.clientPhone = clientPhone;
      record.clientOrigin = clientOrigin;
      record.clientAddress = clientOrigin;
      record.clientService = service;

      if (!record.serviceJobNumber) {
        record.serviceJobNumber = afMaterialMakeJobNumber();
      }

      record.washingRatePerKg = washingRate;
      record.pelletWeight = pelletKg;
      record.actualPelletWeight = pelletKg;
      record.pelletizingRatePerKg = pelletRate;
      record.serviceDiscount =
        Number(modal.querySelector("#editServiceDiscount").value || 0);

      record.dirtPercent = 0;
      record.dirtWeightKg = 0;
      record.netWeight = grossKg;

      /*
       * Do not silently reset a batch balance that washing has
       * already reduced. Only initialise missing legacy values.
       */
      if (record.openingBatchKg == null) {
        record.openingBatchKg = grossKg;
      }

      if (record.batchBalanceKg == null) {
        record.batchBalanceKg = grossKg;
      }

      record.pricePerKg = 0;
      record.transportCost = 0;
      record.totalCost = 0;

      afMaterialRecalculateClientService(record);
    } else {
      const dirtPercent =
        Number(modal.querySelector("#editDirtPercent").value || 0);

      if (dirtPercent < 0 || dirtPercent > 100) {
        alert("Dirt / Waste percentage must be between 0 and 100.");
        return;
      }

      const pricePerKg =
        Number(modal.querySelector("#editPricePerKg").value || 0);

      const transportCost =
        Math.max(Number(modal.querySelector("#editTransportCost").value || 0), 0);
      const miscExpense =
        Math.max(Number(modal.querySelector("#editCompanyMiscExpenses").value || 0), 0);
      const miscReason =
        modal.querySelector("#editCompanyMiscReason").value.trim();

      if (miscExpense > 0 && !miscReason) {
        alert("Please enter the reason / particulars for the miscellaneous expense.");
        return;
      }

      const netKg =
        grossKg * (1 - dirtPercent / 100);

      record.materialSource = "company";
      record.clientName = "";
      record.clientPhone = "";
      record.clientOrigin = "";
      record.clientAddress = "";
      record.clientService = "";

      record.dirtPercent = dirtPercent;
      record.dirtWeightKg =
        Number((grossKg - netKg).toFixed(2));
      record.netWeight =
        Number(netKg.toFixed(2));

      /*
       * Preserve stock movements already posted against this
       * batch. Only reset opening/balance when no washing has
       * been recorded against it yet.
       */
      const alreadyWashed =
        Number(record.totalWashedKg || 0);

      if (alreadyWashed <= 0) {
        record.openingBatchKg =
          Number(netKg.toFixed(2));
        record.batchBalanceKg =
          Number(netKg.toFixed(2));
      }

      record.pricePerKg = pricePerKg;
      record.transportCost = transportCost;
      record.miscellaneousExpenses = miscExpense;
      record.miscellaneousReason = miscReason;
      record.totalCost =
        (netKg * pricePerKg) +
        transportCost +
        miscExpense;

      record.pelletWeight = 0;
      record.actualPelletWeight = 0;
    }

    record.lastEditedAt = new Date().toISOString();

    const user = afMaterialCurrentUser();

    record.lastEditedBy =
      user.fullName ||
      user.employeeName ||
      user.name ||
      user.employeeId ||
      "";

    afMaterialSaveRecords(records);

    modal.remove();

    alert(
      isClient
        ? (
            "Client processing job updated successfully.\n\n" +
            "Status: " + record.serviceStatus + "\n" +
            "Net service charge: " +
            afMaterialMoney(record.serviceTotalDue) + "\n" +
            "Paid: " +
            afMaterialMoney(record.serviceAmountPaid) + "\n" +
            "Outstanding: " +
            afMaterialMoney(record.serviceBalance)
          )
        : "Company material record updated successfully."
    );

    viewMaterialRecords();
  };

  refreshEditPreview();
}

/* =========================================================
   A&F RECYCLE BIN — LINKED TRANSACTION SAFETY
   ========================================================= */
const AF_RECYCLE_BIN_KEY = "afRecycleBin";

function afRecycleBinRead() {
  try {
    const rows = JSON.parse(localStorage.getItem(AF_RECYCLE_BIN_KEY) || "[]");
    return Array.isArray(rows) ? rows : [];
  } catch (e) { return []; }
}

function afRecycleBinSave(rows) {
  localStorage.setItem(AF_RECYCLE_BIN_KEY, JSON.stringify(Array.isArray(rows) ? rows : []));
}

function afRecycleEscape(value) {
  return String(value == null ? "" : value)
    .replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")
    .replace(/"/g,"&quot;").replace(/'/g,"&#039;");
}

function afRecycleBinOpen() {
  const user = typeof afMaterialCurrentUser === "function" ? afMaterialCurrentUser() : {};
  if (String(user.role || "").toLowerCase() !== "director") {
    alert("Only the Director can access the Recycle Bin.");
    return;
  }
  const old = document.getElementById("afRecycleBinModal");
  if (old) old.remove();
  const rows = afRecycleBinRead().slice().sort((a,b)=>String(b.deletedAt||"").localeCompare(String(a.deletedAt||"")));
  const modal = document.createElement("div");
  modal.id = "afRecycleBinModal";
  modal.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.58);display:flex;align-items:center;justify-content:center;z-index:100000;font-family:Arial,sans-serif;padding:10px";
  modal.innerHTML = `<div style="background:white;width:1100px;max-width:98%;max-height:94vh;overflow:auto;border-radius:14px;padding:22px;box-shadow:0 10px 40px rgba(0,0,0,.3)">
    <div style="display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:15px"><div><h2 style="margin:0;color:#0b5d3b">♻️ Recycle Bin</h2><div style="font-size:12px;color:#666;margin-top:4px">Director only • Deleted transactions are excluded from all active accounts and reports</div></div><button id="afCloseRecycleBin" style="padding:8px 14px;border:1px solid #ccc;border-radius:7px;background:white;cursor:pointer">✕ Close</button></div>
    <div style="overflow:auto"><table style="width:100%;min-width:900px;border-collapse:collapse;font-size:12px"><thead><tr style="background:#eef8f2"><th style="padding:9px;text-align:left">Deleted</th><th style="padding:9px;text-align:left">Type</th><th style="padding:9px;text-align:left">Transaction</th><th style="padding:9px;text-align:left">Party</th><th style="padding:9px;text-align:left">Amount</th><th style="padding:9px;text-align:left">Reason</th><th style="padding:9px;text-align:left">Deleted By</th><th style="padding:9px;text-align:left">Action</th></tr></thead><tbody>
    ${rows.length ? rows.map(item=>`<tr style="border-bottom:1px solid #eee"><td style="padding:9px">${afRecycleEscape(item.deletedAt ? new Date(item.deletedAt).toLocaleString() : "-")}</td><td style="padding:9px">${afRecycleEscape(item.type||"Transaction")}</td><td style="padding:9px;font-weight:bold">${afRecycleEscape(item.transactionNo||"-")}</td><td style="padding:9px">${afRecycleEscape(item.party||"-")}</td><td style="padding:9px">${typeof afMaterialMoney === "function" ? afMaterialMoney(item.amount||0) : Number(item.amount||0).toLocaleString()}</td><td style="padding:9px">${afRecycleEscape(item.reason||"-")}</td><td style="padding:9px">${afRecycleEscape(item.deletedBy||"-")}</td><td style="padding:9px;white-space:nowrap"><button onclick="afRecycleBinRestore('${afRecycleEscape(item.recycleId)}')" style="padding:7px 10px;border:0;border-radius:6px;background:#0b5d3b;color:white;cursor:pointer">↩ Restore</button><button onclick="afRecycleBinDeletePermanent('${afRecycleEscape(item.recycleId)}')" style="padding:7px 10px;border:0;border-radius:6px;background:#b42318;color:white;cursor:pointer;margin-left:5px">Delete Permanently</button></td></tr>`).join("") : `<tr><td colspan="8" style="padding:28px;text-align:center;color:#666">Recycle Bin is empty.</td></tr>`}
    </tbody></table></div></div>`;
  document.body.appendChild(modal);
  modal.querySelector("#afCloseRecycleBin").onclick=()=>modal.remove();
}

function afRecycleBinRestore(recycleId) {
  const user = afMaterialCurrentUser();
  if (String(user.role||"").toLowerCase() !== "director") return alert("Only the Director can restore transactions.");
  const bin = afRecycleBinRead();
  const item = bin.find(x=>String(x.recycleId)===String(recycleId));
  if (!item) return alert("Recycle Bin item not found.");
  const pack = item.package || {};
  const material = pack.materialRecord;
  if (material) {
    const active = afMaterialReadRecords();
    const clash = active.some(r=>String(r.id)===String(material.id) || (material.batchNumber && String(r.batchNumber||"")===String(material.batchNumber)));
    if (clash) return alert("Restore stopped because this transaction/batch already exists in active records.");
    active.push(material); afMaterialSaveRecords(active);
  }
  const restoreUnique=(key,items)=>{
    if (!Array.isArray(items) || !items.length) return;
    let active=[]; try { active=JSON.parse(localStorage.getItem(key)||"[]")||[]; } catch(e){}
    if (!Array.isArray(active)) active=[];
    items.forEach(row=>{ const id=String(row.id||row.paymentNo||row.purchaseId||""); if(!active.some(x=>String(x.id||x.paymentNo||x.purchaseId||"")===id && id)) active.push(row); });
    localStorage.setItem(key,JSON.stringify(active));
  };
  restoreUnique("supplierPayments", pack.supplierPayments);
  restoreUnique("afSupplierPurchases", pack.supplierPurchases);
  afRecycleBinSave(bin.filter(x=>String(x.recycleId)!==String(recycleId)));
  const modal=document.getElementById("afRecycleBinModal"); if(modal) modal.remove();
  alert("Transaction restored successfully to all linked active records.");
  afRecycleBinOpen();
}

function afRecycleBinDeletePermanent(recycleId) {
  const user=afMaterialCurrentUser();
  if(String(user.role||"").toLowerCase()!=="director") return alert("Only the Director can permanently delete transactions.");
  const bin=afRecycleBinRead(); const item=bin.find(x=>String(x.recycleId)===String(recycleId));
  if(!item) return alert("Recycle Bin item not found.");
  if(!confirm("PERMANENT DELETE\n\n"+(item.transactionNo||"Transaction")+" will be permanently removed from the Recycle Bin and cannot be restored.\n\nContinue?")) return;
  afRecycleBinSave(bin.filter(x=>String(x.recycleId)!==String(recycleId)));
  const modal=document.getElementById("afRecycleBinModal"); if(modal) modal.remove();
  alert("Transaction permanently deleted."); afRecycleBinOpen();
}

function deleteMaterialRecord(id) {
  const records=afMaterialReadRecords();
  const record=records.find(item=>String(item.id)===String(id));
  if(!record) return alert("Material record not found.");
  const user=afMaterialCurrentUser();
  if(String(user.role||"").toLowerCase()!=="director") return alert("Only the Director can move important transactions to the Recycle Bin.");
  const isClient=String(record.materialSource||"").toLowerCase()==="client";
  const batch=String(record.batchNumber||record.serviceJobNumber||"").trim();

  if(!isClient){
    let washing=[],production=[];
    try{washing=JSON.parse(localStorage.getItem("washingShiftRecords")||"[]")||[];}catch(e){}
    try{production=JSON.parse(localStorage.getItem("productionRecords")||"[]")||[];}catch(e){}
    const washingLinked=Array.isArray(washing)&&washing.some(w=>batch&&[w.batchNumber,w.sourceBatchNumber,w.masterBatchNumber].map(v=>String(v||"").trim()).includes(batch));
    const productionLinked=Array.isArray(production)&&production.some(p=>batch&&([p.batchNumber,p.sourceBatchNumber,p.masterBatchNumber].map(v=>String(v||"").trim()).includes(batch)||(Array.isArray(p.washedSources)&&p.washedSources.some(src=>String(src.sourceBatchNumber||"").trim()===batch))));
    if(washingLinked||productionLinked||Number(record.totalWashedKg||0)>0) return alert("TRANSACTION CANNOT BE MOVED TO RECYCLE BIN YET\n\nBatch "+(batch||"-")+" has linked washing or production activity.\n\nReverse the downstream activity first so stock history remains correct.");
  }

  const reason=prompt("Reason for moving "+(batch||"this transaction")+" to the Recycle Bin:","");
  if(reason===null) return;
  if(!String(reason).trim()) return alert("Please enter a reason for deletion.");

  let supplierPayments=[]; try{supplierPayments=JSON.parse(localStorage.getItem("supplierPayments")||"[]")||[];}catch(e){}
  let supplierPurchases=[]; try{supplierPurchases=JSON.parse(localStorage.getItem("afSupplierPurchases")||"[]")||[];}catch(e){}
  const linkedPayments=Array.isArray(supplierPayments)?supplierPayments.filter(p=>String(p.materialRecordId||"")===String(record.id||"")||(batch&&String(p.batchNumber||"").trim()===batch)):[];
  const linkedPurchases=Array.isArray(supplierPurchases)?supplierPurchases.filter(p=>String(p.materialRecordId||"")===String(record.id||"")||(batch&&String(p.batchNumber||"").trim()===batch)):[];

  if(!confirm("MOVE TO RECYCLE BIN\n\nTransaction: "+(batch||"-")+"\nParty: "+(record.supplierName||record.clientName||"-")+"\nAmount: "+afMaterialMoney(isClient?(record.serviceTotalDue||0):(record.totalCost||0))+"\nLinked supplier payments: "+linkedPayments.length+"\n\nIt will disappear from all active accounts and reports but can be restored by the Director.\n\nContinue?")) return;

  const recycleItem={
    recycleId:"RB-"+Date.now()+"-"+Math.random().toString(36).slice(2,7).toUpperCase(),
    type:isClient?"Client Processing":"Supplier Purchase",
    transactionNo:batch||String(record.id||""), party:record.supplierName||record.clientName||"",
    amount:Number(isClient?(record.serviceTotalDue||0):(record.totalCost||0)), reason:String(reason).trim(),
    deletedAt:new Date().toISOString(), deletedBy:user.fullName||user.employeeName||user.name||user.employeeId||"Director",
    package:{materialRecord:JSON.parse(JSON.stringify(record)),supplierPayments:JSON.parse(JSON.stringify(linkedPayments)),supplierPurchases:JSON.parse(JSON.stringify(linkedPurchases))}
  };
  const bin=afRecycleBinRead(); bin.push(recycleItem); afRecycleBinSave(bin);

  afMaterialSaveRecords(records.filter(x=>String(x.id)!==String(record.id)));
  if(!isClient){
    localStorage.setItem("supplierPayments",JSON.stringify((Array.isArray(supplierPayments)?supplierPayments:[]).filter(p=>!linkedPayments.includes(p))));
    localStorage.setItem("afSupplierPurchases",JSON.stringify((Array.isArray(supplierPurchases)?supplierPurchases:[]).filter(p=>!linkedPurchases.includes(p))));
  }
  const open=document.getElementById("afMaterialRecordsModal"); if(open) open.remove();
  alert("Transaction moved to Recycle Bin and removed from all active accounts and reports.");
  viewMaterialRecords();
}

