  function updateWeek() {

    if (!assessmentDate.value) {
      return;
    }

const start =
getWeekStart(
assessmentDate.value
      );

const end =
getWeekEnd(start);

modal.querySelector(
      "#qdWeekDisplay"
    ).value =
readableDate(start) +
      " – " +
readableDate(end);
  }


  function updateEmployeeDetails() {

const employee =
allEmployees.find(item =>
        String(item.employeeId) ===
        String(employeeSelect.value)
      );

const photo =
modal.querySelector(
        "#qdEmployeePhoto"
      );

const noPhoto =
modal.querySelector(
        "#qdNoPhoto"
      );

    if (!employee) {

modal.querySelector(
        "#qdEmployeeId"
      ).value = "";

modal.querySelector(
        "#qdDepartment"
      ).value = "";

modal.querySelector(
        "#qdPosition"
      ).value = "";

modal.querySelector(
        "#qdTeam"
      ).value = "";

photo.style.display = "none";
photo.removeAttribute("src");

noPhoto.style.display = "block";

      return;
    }


const team =
getEmployeeTeam(
employee.employeeId
      );


modal.querySelector(
      "#qdEmployeeId"
    ).value =
employee.employeeId || "";


modal.querySelector(
      "#qdDepartment"
    ).value =
employee.department || "";


modal.querySelector(
      "#qdPosition"
    ).value =
getEmployeePosition(employee);


modal.querySelector(
      "#qdTeam"
    ).value =
      team
        ? team.name || ""
        : "Not Assigned";


    if (employee.passportPhoto) {

photo.src =
employee.passportPhoto;

photo.style.display =
        "block";

noPhoto.style.display =
        "none";

    } else {

photo.style.display =
        "none";

photo.removeAttribute("src");

noPhoto.style.display =
        "block";
    }
  }


  function calculateTotal() {

    let total = 0;

    modal
      .querySelectorAll(".qdScore")
      .forEach(input => {

        let score =
          Number(input.value);

        if (
Number.isNaN(score)
        ) {
          score = 0;
        }

        if (score < 0) {
          score = 0;
        }

        if (score > 10) {
          score = 10;
        }

        total += score;
      });


modal.querySelector(
      "#qdTotalScore"
    ).textContent =
total.toFixed(0);

    return total;
  }


  function collectAssessmentData(
requireComplete = true
  ) {

const employee =
allEmployees.find(item =>
        String(item.employeeId) ===
        String(employeeSelect.value)
      );


    if (!employee) {

      alert(
        "Please select the employee being assessed."
      );

      return null;
    }


    if (!assessmentDate.value) {

      alert(
        "Please select the assessment date."
      );

      return null;
    }


const scores = {};

    let total = 0;

    let complete = true;


    modal
      .querySelectorAll(".qdScore")
      .forEach(input => {

        if (
input.value === ""
        ) {
          complete = false;
        }

const score =
          Number(input.value);

        if (
          !Number.isFinite(score) ||
          score < 0 ||
          score > 10
        ) {
          complete = false;
        }

        scores[
input.dataset.key
        ] =
Number.isFinite(score)
            ? score
            : 0;

        total +=
Number.isFinite(score)
            ? score
            : 0;
      });


    if (
requireComplete&&
      !complete
    ) {

      alert(
        "Please score all 10 Quality & Discipline items from 0 to 10."
      );

      return null;
    }


const weekStart =
getWeekStart(
assessmentDate.value
      );

const weekEnd =
getWeekEnd(
weekStart
      );

const team =
getEmployeeTeam(
employee.employeeId
      );


    return {
      employee,
      team,
      scores,
      total:
        Number(total.toFixed(0)),
weekStart,
weekEnd
    };
  }


