getAFManagerCurrentUser();


const oldCards =
document.getElementById(
        "afManagerDailyStatusCards"
      );


    if (oldCards) {
oldCards.remove();
    }


    if (
      !user ||
user.role !== "Manager"
    ) {

      return;

    }


const main =
document.querySelector(
        "#mainApplication .main"
      );


