  /* =======================================================
     CONNECT TO EXISTING SYSTEM SETTINGS
     WITHOUT REPLACING systemSettings()
     ======================================================= */

  function connectToSystemSettings() {

    /*
     * Locate the existing System Settings
     * using one of its known buttons.
     */
const teamButton =
document.querySelector(
        "#teamSettingsBtn"
      );


    if (!teamButton) {
      return;
    }


const settingsModal =
teamButton.closest(
        'div[style*="position: fixed"], div[style*="position:fixed"]'
      );


    if (!settingsModal) {
      return;
    }


    /*
     * Do not add twice.
     */
    if (
settingsModal.querySelector(
        "#afDateTimeSettingsBtn"
      )
    ) {

      return;
    }


    /*
     * Director only.
     */
    let currentUser = null;


    try {

currentUser =
JSON.parse(
localStorage.getItem(
            "currentUser"
          ) || "null"
        );

    } catch (error) {

currentUser = null;
    }


    if (
      !currentUser ||
currentUser.role !==
        "Director"
    ) {

      return;
    }


const grid =
teamButton.parentElement;


    if (!grid) {
      return;
    }


const button =
document.createElement(
        "button"
      );


button.id =
      "afDateTimeSettingsBtn";


    if (
typeof systemSettingsButtonStyle ===
      "function"
    ) {

button.style.cssText =
systemSettingsButtonStyle();

    } else {

button.style.cssText = `
        padding:16px;
        border:1px solid #ddd;
        border-radius:10px;
background:white;
cursor:pointer;
text-align:left;
      `;
    }


button.innerHTML = `
📅
<strong>
        Date & Time Format
</strong>

<span>
        Date format and 12/24-hour clock
</span>
    `;


button.onclick =
      function() {

settingsModal.remove();

manageAFDateTimeSettings();
      };


grid.appendChild(
      button
    );
  }


  /*
   * System Settings is created dynamically,
   * therefore watch for it safely.
   */

const observer =
    new MutationObserver(
      function() {

connectToSystemSettings();
      }
    );


observer.observe(
document.body,
    {
childList:true,
subtree:true
    }
  );


connectToSystemSettings();


