  /* =======================================================
     SALES / DELIVERY HISTORY
     ======================================================= */

  function deliveryDetails(r) {

    if (
      String(
r.deliveryType || ""
      ).toLowerCase() ===
      "pellets"
    ) {

      return (
        (
r.pelletType ||
          "Pellets"
        ) +
        " — " +
        Number(
r.pelletKg || 0
        ).toLocaleString() +
        " kg"
      );

    }

const items =
Array.isArray(
r.items
      )
        ? r.items
        : [];

    return items.length

      ? items
          .map(
i =>
              (
i.name ||
i.key ||
                "Poles"
              ) +
              " × " +
              Number(
i.quantity || 0
              ).toLocaleString()
          )
          .join(", ")

      : Number(
r.totalPoles || 0
        ).toLocaleString() +
        " poles";
  }

