/* =========================================================
   PRINT COMPANY LETTER
   ========================================================= */

function printLetter(letter){

  if(
    !requireDirector() ||
    !letter
  ){
    return;
  }


const w=
window.open(
      "",
      "_blank",
      "width=950,height=850"
    );


  if(!w){

    alert(
      "Please allow pop-ups so the company letter can open."
    );

    return;
  }


const draft=
    String(
letter.status||
      "DRAFT"
    ).toUpperCase()==="DRAFT";


const br=v=>
    esc(v||"")
      .replace(
        /\n/g,
        "<br>"
      );


w.document.write(`

<!DOCTYPE html>

<html>

<head>

<meta charset="UTF-8">

<title>
${esc(
letter.reference||
  "Company Letter"
)}
</title>


<style>

${smartStyles()}


body{
  font-size:12.5px;
  line-height:1.55;
}
.letter-meta,
.letter-to,
.letter-subject,
.letter-body,
.letter-signature,
.letter-extra,
.draft-mark{
  margin-left:32px;
  margin-right:32px;
}

.letter-subject{
  margin-left:50px;
  }
.letter-meta{
display:grid;
  grid-template-columns:1fr 1fr;
  gap:12px 24px;
  margin:8px 0 20px;
}


.letter-meta>div{
  padding:7px 0;
  border-bottom:1px solid #dce5e0;
}


.letter-to{
  margin-bottom:18px;
}


.letter-subject{
  margin:18px 0;
  font-weight:900;
text-transform:uppercase;
text-decoration:underline;
}


.letter-body{
  min-height:280px;
  line-height:1.7;
}


.letter-signature{
  margin-top:38px;
  width:310px;
}


.signature-space{
  height:46px;
}


.signature-line{
  border-top:1px solid #333;
  padding-top:5px;
}


.letter-extra{
  margin-top:24px;
  padding-top:10px;
  border-top:1px solid #e0e6e2;
  font-size:11px;
}


.draft-mark{
  margin-bottom:14px;
  padding:7px 10px;
  border:1px dashed #b42318;
  color:#b42318;
font-weight:bold;
text-align:center;
}


.print-btn{
  border:0;
  background:#0b5d3b;
color:white;
  padding:10px 18px;
  border-radius:7px;
font-weight:bold;
cursor:pointer;
}

</style>

</head>


<body>


<div class="af-no-print">

<button
class="print-btn"
onclick="window.print()"
>
Print / Save as PDF
</button>

</div>


${smartHeader(
  ""
)}


${
draft
  ? `
<div class="draft-mark">
DRAFT — NOT YET ISSUED
</div>
  `
  : ""
}


<div class="letter-meta">

<div>

<b>Ref:</b>

${esc(
letter.reference||
"-"
)}

</div>


<div style="text-align:right">

<b>Date:</b>

${esc(
niceDate(
letter.date
)
)}

</div>

</div>


<div class="letter-to">

<b>To:</b>

<br>

${esc(
letter.recipientName||
""
)}

<br>

${
letter.recipientOrganisation
  ? esc(
letter.recipientOrganisation
    )+
    "<br>"
  : ""
}

${br(
letter.recipientAddress
)}

</div>


<div class="letter-subject">

RE:
${esc(
letter.subject||
""
)}

</div>


<div style="margin-bottom:15px">

${esc(
letter.salutation||
"Dear Sir/Madam,"
)}

</div>


<div class="letter-body">

${br(
letter.body
)}

</div>


<div class="letter-signature">

<div>

${esc(
letter.closing||
"Yours faithfully,"
)}

</div>


<div class="signature-space">
</div>


<div class="signature-line">

<b>
${esc(
letter.signatoryName||
""
)}
</b>

<br>

${esc(
letter.signatoryTitle||
"Director"
)}

<br>

A&amp;F Wekavera Ltd

</div>

</div>


${
letter.cc||
letter.attachments

  ? `

<div class="letter-extra">

${
letter.cc
  ? `
<div>

<b>CC:</b>

<br>

${br(
letter.cc
)}

</div>
  `
  : ""
}


${
letter.attachments
  ? `
<div style="margin-top:8px">

<b>Attachments:</b>

<br>

${br(
letter.attachments
)}

</div>
  `
  : ""
}

</div>

  `

  : ""
}


${smartFooter(
  "Official Correspondence"
)}


</body>

</html>

`);


w.document.close();

w.focus();

}


