/* =========================================================
   MAIN ENTRY
   ========================================================= */

function openTVSLA() {

    if (!tvslaAllowed()) {

        alert(
            "Access Denied\n\n" +
            "TVSLA is available only to " +
            "the Director and Secretary."
        );

        return;
    }


    /*
     * Secretary must go directly
     * to Transaction Entry.
     */

    if (tvslaSecretary()) {

openTVSLATransactionEntry();

        return;
    }


openTVSLADashboard();
}


