/* =========================================================
   TRANSACTION ENTRY
   Director + Secretary
   ========================================================= */

function openTVSLATransactionEntry() {

    if (!tvslaAllowed()) {

        alert("Access Denied");
        return;
    }


const members =
tvslaMembers();


const memberOptions =
        members
            .filter(
                member =>
member.active !== false
            )
            .map(
                member => `

<option
                        value="${tvslaEscape(member.id)}"
>
                        ${tvslaEscape(member.name)}
</option>

                `
            )
            .join("");


const modal =
tvslaModal(
            "TVSLA Transaction Entry",
            `

<div style="
                background:#eef7f1;
                border:1px solid #cfe3d6;
                padding:11px;
                border-radius:9px;
                margin-bottom:14px;
                font-size:12px;
            ">

                Logged in as:
<b>
                    ${tvslaEscape(
tvslaCurrentUserName()
                    )}
</b>

&nbsp;|&nbsp;

                Role:
<b>
                    ${tvslaEscape(
tvslaRole()
                    )}
</b>

</div>


<form id="tvslaTransactionForm">

<div style="
display:grid;
                    grid-template-columns:
                        repeat(
                            auto-fit,
minmax(210px,1fr)
                        );
                    gap:12px;
                ">

<label>
                        Date
<input
                            id="tvslaTransactionDate"
                            type="date"
                            value="${tvslaToday()}"
                            required
                            style="${tvslaInputStyle()}"
>
</label>


<label>
                        Member

<select
                            id="tvslaTransactionMember"
                            required
                            style="${tvslaInputStyle()}"
>

<option value="">
                                Select Member
</option>

                            ${memberOptions}

</select>

</label>


<label>
                        Transaction Type

<select
                            id="tvslaTransactionType"
                            required
                            style="${tvslaInputStyle()}"
>

<option value="">
                                Select Transaction
</option>

<option value="Savings">
                                Savings / Contribution
</option>

<option value="Withdrawal">
                                Withdrawal
</option>

<option value="Loan Repayment">
                                Loan Repayment
</option>

<option value="Dividend / Interest">
                                Dividend / Interest
</option>

<option value="Other Income">
                                Other Income
</option>

</select>

</label>


<label>
                        Amount (UGX)

<input
                            id="tvslaTransactionAmount"
                            type="number"
                            min="1"
                            step="1"
                            required
                            style="${tvslaInputStyle()}"
>

</label>


<label>
                        Payment Method

<select
                            id="tvslaPaymentMethod"
                            style="${tvslaInputStyle()}"
>

<option value="Cash">
                                Cash
</option>

<option value="Mobile Money">
                                Mobile Money
</option>

<option value="Bank">
                                Bank
</option>

<option value="Other">
                                Other
</option>

</select>

</label>


<label>
                        Receipt / Reference

<input
                            id="tvslaReference"
                            type="text"
                            placeholder="Optional"
                            style="${tvslaInputStyle()}"
>

</label>

</div>


<label style="
display:block;
                    margin-top:12px;
                ">

                    Notes

<textarea
                        id="tvslaTransactionNotes"
                        rows="3"
                        style="${tvslaInputStyle()}"
></textarea>

</label>


<div style="
                    margin-top:15px;
display:flex;
                    gap:8px;
flex-wrap:wrap;
                ">

                    ${tvslaButton(
                        "Save Transaction",
                        "tvslaSaveTransactionBtn"
                    )}

                    ${
tvslaDirector()
                        ? tvslaButton(
                            "Back to Dashboard",
                            "tvslaBackDashboardBtn",
                            true
                        )
                        : ""
                    }

</div>

</form>

            `
        );


const form =
modal.querySelector(
            "#tvslaTransactionForm"
        );


form.onsubmit =
        function(event) {

event.preventDefault();


const memberId =
modal.querySelector(
                    "#tvslaTransactionMember"
                ).value;


const member =
tvslaMembers()
                    .find(
                        item =>
item.id ===
memberId
                    );


            if (!member) {

                alert(
                    "Please select a TVSLA member."
                );

                return;
            }


const amount =
                Number(
modal.querySelector(
                        "#tvslaTransactionAmount"
                    ).value
                );


            if (
                !Number.isFinite(amount) ||
                amount <= 0
            ) {

                alert(
                    "Enter a valid transaction amount."
                );

                return;
            }


const transactions =
tvslaTransactions();


transactions.push({

                id:
tvslaID("TXN"),

                date:
modal.querySelector(
                        "#tvslaTransactionDate"
                    ).value,

memberId:
member.id,

memberName:
member.name,

                type:
modal.querySelector(
                        "#tvslaTransactionType"
                    ).value,

                amount,

paymentMethod:
modal.querySelector(
                        "#tvslaPaymentMethod"
                    ).value,

                reference:
modal.querySelector(
                        "#tvslaReference"
                    ).value.trim(),

                notes:
modal.querySelector(
                        "#tvslaTransactionNotes"
                    ).value.trim(),

enteredBy:
tvslaCurrentUserName(),

enteredByRole:
tvslaRole(),

createdAt:
Date.now()

            });


tvslaWrite(
TVSLA_KEYS.transactions,
                transactions
            );


            alert(
                "TVSLA transaction saved successfully.\n\n" +
                "This transaction has NOT affected " +
                "the factory accounts."
            );


            /*
             * Secretary stays in transaction entry.
             * Director returns to TVSLA dashboard.
             */

            if (tvslaDirector()) {

openTVSLADashboard();

            } else {

openTVSLATransactionEntry();

            }

        };


const back =
modal.querySelector(
            "#tvslaBackDashboardBtn"
        );


    if (back) {

back.onclick =
openTVSLADashboard;
    }
}


